-- Only Mercury (closest to the sun) stays joinable; all other seeded servers offline.
UPDATE servers
SET status = 'online'
WHERE id = '11111111-1111-4111-8111-111111111111';

UPDATE servers
SET status = 'offline'
WHERE id IN (
  '22222222-2222-4222-8222-222222222222', -- Venus
  '33333333-3333-4333-8333-333333333333', -- Earth
  '44444444-4444-4444-8444-444444444444', -- Mars
  '55555555-5555-4555-8555-555555555555', -- Jupiter (v4)
  '55555555-5555-5555-8555-555555555555', -- Jupiter (legacy pre-011)
  '66666666-6666-4666-8666-666666666666', -- Saturn (v4)
  '66666666-6666-6666-8666-666666666666', -- Saturn (legacy)
  '77777777-7777-4777-8777-777777777777', -- Uranus (v4)
  '77777777-7777-7777-8777-777777777777', -- Uranus (legacy)
  '88888888-8888-4888-8888-888888888888', -- Neptune (v4)
  '88888888-8888-8888-8888-888888888888', -- Neptune (legacy)
  '99999999-9999-4999-8999-999999999999', -- Pluto (v4)
  '99999999-9999-9999-8999-999999999999'  -- Pluto (legacy)
);
